import React, { useState } from 'react';
import { useDropzone } from 'react-dropzone';

const CVUpload = ({ file, onChange = () => {}, error }) => {
  const [fileError, setFileError] = useState('');
  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    accept: {
      'application/pdf': ['.pdf'],
      'application/msword': ['.doc'],
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document': ['.docx'],
    },
    maxSize: 5 * 1024 * 1024,
    multiple: false,
    onDrop: (accepted, rejected) => {
      if (rejected.length) {
        const codes = rejected.flatMap(item => item.errors.map(reason => reason.code));
        setFileError(codes.includes('too-many-files') ? 'Please choose one CV at a time.'
          : codes.includes('file-too-large') ? 'Your CV must be 5 MB or smaller.'
          : 'Please choose a PDF, DOC, or DOCX file.');
        return;
      }
      if (accepted.length) {
        setFileError('');
        onChange(accepted[0]);
      }
    },
  });
  const message = fileError || error;

  return (
    <div className="form-group">
      <span className="form-label" id="cv-label">CV / résumé</span>
      <div {...getRootProps({
        className: `cv-upload${isDragActive ? ' is-dragging' : ''}`,
        role: 'button',
        'aria-labelledby': 'cv-label cv-title',
        'aria-describedby': message ? 'cv-error' : 'cv-hint',
      })}>
        <input {...getInputProps({ id: 'cv', name: 'cv' })} />
        <div className="upload-symbol" aria-hidden="true">↑</div>
        <div>
          <strong id="cv-title">{isDragActive ? 'Drop your CV here' : 'Drop your CV here, or click to browse'}</strong>
          <p className="field-hint" id="cv-hint">One PDF, DOC, or DOCX · Up to 5 MB</p>
        </div>
      </div>
      {file && (
        <div className="cv-selected" role="status">
          <span><strong>{file.name}</strong><small>{(file.size / 1024).toFixed(1)} KB · Selected</small></span>
          <button type="button" className="cv-remove" onClick={() => { onChange(null); setFileError(''); }} aria-label={`Remove ${file.name}`}>Remove</button>
        </div>
      )}
      {message && <p className="form-error" id="cv-error" role="alert">{message}</p>}
    </div>
  );
};

export default CVUpload;
